class MinHeap {
  constructor() {
    this.heap = [];
  }
  size() {
    return this.heap.length;
  }
  peek() {
    return this.heap[0];                         // the smallest value; undefined if empty
  }
  push(x) {
    this.heap.push(x);                           // 1. add at the end
    let i = this.heap.length - 1;
    while (i > 0) {                              // 2. sift up
      const parent = Math.floor((i - 1) / 2);
      if (this.heap[parent] <= this.heap[i]) break;   // parent is smaller or equal: done
      this.swap(i, parent);
      i = parent;
    }
  }
  pop() {
    if (this.heap.length === 0) return undefined;
    const top = this.heap[0];                    // 1. the smallest value
    const last = this.heap.pop();                // 2. take the last value off the end
    if (this.heap.length > 0) {
      this.heap[0] = last;                       //    and put it on top
      let i = 0;
      while (true) {                             // 3. sift down
        const left = 2 * i + 1, right = 2 * i + 2;
        let smallest = i;
        if (left < this.heap.length && this.heap[left] < this.heap[smallest]) smallest = left;
        if (right < this.heap.length && this.heap[right] < this.heap[smallest]) smallest = right;
        if (smallest === i) break;               // both children are bigger or equal: done
        this.swap(i, smallest);
        i = smallest;
      }
    }
    return top;
  }
  swap(a, b) {
    [this.heap[a], this.heap[b]] = [this.heap[b], this.heap[a]];
  }
}

class MinHeap {
    private final List<Integer> heap = new ArrayList<>();

    int size() {
        return heap.size();
    }

    Integer peek() {
        return heap.isEmpty() ? null : heap.get(0);       // the smallest value
    }

    void push(int x) {
        heap.add(x);                                      // 1. add at the end
        int i = heap.size() - 1;
        while (i > 0) {                                   // 2. sift up
            int parent = (i - 1) / 2;
            if (heap.get(parent) <= heap.get(i)) break;   // parent is smaller or equal: done
            swap(i, parent);
            i = parent;
        }
    }

    Integer pop() {
        if (heap.isEmpty()) return null;
        int top = heap.get(0);                            // 1. the smallest value
        int last = heap.remove(heap.size() - 1);          // 2. take the last value off the end
        if (!heap.isEmpty()) {
            heap.set(0, last);                            //    and put it on top
            int i = 0;
            while (true) {                                // 3. sift down
                int left = 2 * i + 1, right = 2 * i + 2;
                int smallest = i;
                if (left < heap.size() && heap.get(left) < heap.get(smallest)) smallest = left;
                if (right < heap.size() && heap.get(right) < heap.get(smallest)) smallest = right;
                if (smallest == i) break;                 // both children are bigger or equal: done
                swap(i, smallest);
                i = smallest;
            }
        }
        return top;
    }

    private void swap(int a, int b) {
        int t = heap.get(a);
        heap.set(a, heap.get(b));
        heap.set(b, t);
    }
}

class MinHeap {
    vector<int> heap;

public:
    int size() {
        return heap.size();
    }

    int peek() {
        if (heap.empty()) throw out_of_range("peek on an empty heap");
        return heap[0];                               // the smallest value
    }

    void push(int x) {
        heap.push_back(x);                            // 1. add at the end
        int i = heap.size() - 1;
        while (i > 0) {                               // 2. sift up
            int parent = (i - 1) / 2;
            if (heap[parent] <= heap[i]) break;       // parent is smaller or equal: done
            swap(heap[i], heap[parent]);
            i = parent;
        }
    }

    int pop() {
        if (heap.empty()) throw out_of_range("pop on an empty heap");
        int top = heap[0];                            // 1. the smallest value
        heap[0] = heap.back();                        // 2. move the last value to the top
        heap.pop_back();
        int i = 0, n = heap.size();
        while (true) {                                // 3. sift down
            int left = 2 * i + 1, right = 2 * i + 2;
            int smallest = i;
            if (left < n && heap[left] < heap[smallest]) smallest = left;
            if (right < n && heap[right] < heap[smallest]) smallest = right;
            if (smallest == i) break;                 // both children are bigger or equal: done
            swap(heap[i], heap[smallest]);
            i = smallest;
        }
        return top;
    }
};
